    SPECIAL: CopilotDocV1.Role.Special,
    TOKEN: CopilotDocV1.Role.Token,
    TRAP: CopilotDocV1.Role.Trap,
  }
  return profToRole[info.prof] ?? CopilotDocV1.Role.Unknown
}

