import camelcaseKeys from 'camelcase-keys'
import { CopilotInfo } from 'zoot-plus-client'

import { CopilotDocV1 } from 'models/copilot.schema'

import { i18n } from '../i18n/i18n'
import { findOperatorsByIdentity } from './operator'

export function toCopilotOperation(apiOperation: CopilotInfo): CopilotDocV1.Operation {
  try {
    const json = JSON.parse(apiOperation.content)
    const operation: CopilotDocV1.Operation = camelcaseKeys(json, {
      deep: true,
    })
    return migrateOperation(operation)
  } catch (e) {
    console.error('Failed to parse operation', apiOperation, e)
  }

  return {
    doc: {
      title: i18n.models.converter.invalid_operation_content,
    },
    minimumRequired: 'v4.0.0',
    actions: [],
    stageName: '',
  }
}

/**
 * role 为空串（含 null）视为未填写，就地删掉该字段，避免原样导出。
 * 三条导入链路共用：migrateOperation（API 加载与 editor2）与 toEditableOperation（源码粘贴）。
 */
export function stripEmptyRole<T extends object>(action: T): T {
  if ('role' in action && !(action as { role?: unknown }).role) {
    delete (action as { role?: unknown }).role
  }
  return action
}

export function migrateOperation(operation: CopilotDocV1.Operation): CopilotDocV1.Operation {
  // role 为空串视为未填写，导入链路统一在此清掉，避免原样导出
  operation.actions?.forEach(stripEmptyRole)
  if (operation.version === 2) {
    // in version 2, the module property is set to the index of the module in the modules array,
    // we need to convert it using the correct CopilotDocV1.Module mapping
    return {
      ...operation,
      version: CopilotDocV1.VERSION,
      opers: migrateOperatorsModule(operation.opers),
      // groups 内的干员同样存在 v2 模组索引，需要一并迁移
      groups: operation.groups?.map((group) => ({
        ...group,
        opers: migrateOperatorsModule(group.opers),
      })),
    }
  }
  return operation
}

function migrateOperatorsModule(opers?: CopilotDocV1.Operator[]): CopilotDocV1.Operator[] | undefined {
  return opers?.map((operator) => {
    if (operator.requirements?.module === undefined) {
      return operator
    }
    const modules = findOperatorsByIdentity(operator)[0]?.modules
    if (!modules) {
      return operator
    }
    const actualModuleName = modules[operator.requirements.module]
    const actualModule =
      actualModuleName in CopilotDocV1.Module
        ? (CopilotDocV1.Module[actualModuleName] as CopilotDocV1.Module)
        : CopilotDocV1.Module.Default
    return {
      ...operator,
      requirements: {
        ...operator.requirements,
        module: actualModule,
      },
    }
  })
}
  )

  const syncOperators = useCallback(
    async (
      tokenToUse: string,
      options: {
        enableMatching: boolean
        showError: boolean
        showSuccess: boolean
      },
    ) => {
      const normalizedToken = tokenToUse.trim()

      if (!normalizedToken) {
        if (options.showError) {
          setError(t.components.OperatorMatcher.token_required)
        }
        return false
      }

      if (options.showError) {
        setError('')
      }

      setLoading(true)

      try {
        const response = await fetch(YITULIU_OPERATOR_API_URL, {
          headers: {
            Authorization: normalizedToken,
          },
        })
        const payload = (await response.json()) as OpenApiResult

        if (!response.ok || payload.code !== 200) {
          throw new Error(payload.message || t.components.OperatorMatcher.fetch_failed)
        }

        const operators = normalizeYituliuOwnedOperators(payload.data)

        if (operators.length === 0) {
          throw new Error(t.components.OperatorMatcher.no_operators)
        }

        applyOperators(operators, {
          enableMatching: options.enableMatching,
          token: normalizedToken,
        })

        if (options.showSuccess) {
          AppToaster.show({
            intent: 'success',
            message: t.components.OperatorMatcher.imported({
              count: operators.length,
            }),
          })
        }

        return true
      } catch (error) {
        if (options.showError) {
          setError(error instanceof Error ? error.message : t.components.OperatorMatcher.fetch_failed)
        }
        return false
      } finally {
        setLoading(false)
      }
    },
    [applyOperators, t],
  )

  useEffect(() => {
    if (autoSyncAttempted.current || !settings.token) {
      return
    }

    autoSyncAttempted.current = true
    void syncOperators(settings.token, {
      enableMatching: false,
      showError: false,
      showSuccess: false,
    })
  }, [settings.token, syncOperators])

  const importOperators = async () => {
    autoSyncAttempted.current = true
    const imported = await syncOperators(token, {
      enableMatching: true,
      showError: true,
      showSuccess: true,
    })

    if (imported) {
      closeDialog()
    }
  }

  /**
   * 从本地 JSON 文件导入干员数据。
   * 兼容两种结构：
   * 1) 完整 OpenAPI 响应：{ code, data, message }
   * 2) 只有 data 部分的对象
   */
  const importFromFile = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.currentTarget.files?.[0]
    // 立刻清空，保证同一文件再次选择仍能触发 change
    event.currentTarget.value = ''
    if (!file) {
      return
    }

    setError('')

    try {
      const text = await file.text()
      // 去掉可能存在的 UTF-8 BOM
      const normalized = text.replace(/^\uFEFF/, '')
      let raw: OpenApiResult | { data?: unknown }
      try {
        raw = JSON.parse(normalized) as OpenApiResult | { data?: unknown }
      } catch {
        setError(t.components.OperatorMatcher.invalid_file)
        return
      }

      const data = (raw as OpenApiResult).data ?? raw
      const operators = normalizeYituliuOwnedOperators(data)

      if (operators.length === 0) {
        throw new Error(t.components.OperatorMatcher.no_operators)
      }

      // 本地导入不改动 token，用户下次仍可用原 token 同步
      applyOperators(operators, { enableMatching: true })

      AppToaster.show({
        intent: 'success',
        message: t.components.OperatorMatcher.imported({
          count: operators.length,
        }),
      })

      closeDialog()
    } catch (err) {
      setError(err instanceof Error ? err.message : t.components.OperatorMatcher.invalid_file)
    }
  }

  const toggleMode = (mode: OperatorMatchMode) => {
    if (settings.ownedOperators.length === 0) {
      return
    }

    const modes = settings.modes.includes(mode)
      ? settings.modes.filter((item) => item !== mode)
      : [...settings.modes, mode]

    if (modes.length === 0) {
      return
    }

    setSettings((current) => ({ ...current, modes }))
  }

  const modeOptions: Array<{ mode: OperatorMatchMode; text: string }> = [
    { mode: 'ready', text: t.components.OperatorMatcher.ready },
    { mode: 'borrow', text: t.components.OperatorMatcher.borrow },
    { mode: 'train', text: t.components.OperatorMatcher.train },
    { mode: 'blocked', text: t.components.OperatorMatcher.blocked },
  ]
  const showStaleReminder = isOperatorDataStale(settings.lastChangedAt)

  return (
    <>
      <div className="flex flex-wrap items-center gap-1">
        <Button
          minimal
          className="!px-3"
          icon="cog"
          active={settings.enabled && settings.ownedOperators.length > 0}
#!/usr/bin/env python3
"""
Quick validation script for skills - minimal version
"""

import re
import sys
from pathlib import Path

import yaml

MAX_SKILL_NAME_LENGTH = 64


def validate_skill(skill_path):
    """Basic validation of a skill"""
    skill_path = Path(skill_path)

    skill_md = skill_path / "SKILL.md"
    if not skill_md.exists():
        return False, "SKILL.md not found"

    content = skill_md.read_text()
    if not content.startswith("---"):
        return False, "No YAML frontmatter found"

    match = re.match(r"^---\n(.*?)\n---", content, re.DOTALL)
    if not match:
        return False, "Invalid frontmatter format"

    frontmatter_text = match.group(1)

    try:
        frontmatter = yaml.safe_load(frontmatter_text)
        if not isinstance(frontmatter, dict):
            return False, "Frontmatter must be a YAML dictionary"
    except yaml.YAMLError as e:
        return False, f"Invalid YAML in frontmatter: {e}"

    allowed_properties = {"name", "description", "license", "allowed-tools", "metadata"}

    unexpected_keys = set(frontmatter.keys()) - allowed_properties
    if unexpected_keys:
        allowed = ", ".join(sorted(allowed_properties))
        unexpected = ", ".join(sorted(unexpected_keys))
        return (
            False,
            f"Unexpected key(s) in SKILL.md frontmatter: {unexpected}. Allowed properties are: {allowed}",
        )

    if "name" not in frontmatter:
        return False, "Missing 'name' in frontmatter"
    if "description" not in frontmatter:
        return False, "Missing 'description' in frontmatter"

